```delphi
program ArrayIntersection;

{$APPTYPE CONSOLE}

uses
  SysUtils, Generics.Collections;

function ArrayIntersection(const ar1, ar2: array of Integer): TArray<Integer>;
var
  Set1, Set2: TDictionary<Integer, Boolean>;
  Intersection: TList<Integer>;
  Value: Integer;
begin
  Set1 := TDictionary<Integer, Boolean>.Create;
  Set2 := TDictionary<Integer, Boolean>.Create;
  Intersection := TList<Integer>.Create;
  try
    // Add elements of ar1 to Set1
    for Value in ar1 do
      Set1.Add(Value, True);

    // Add elements of ar2 to Set2 and check for intersection
    for Value in ar2 do
    begin
      if Set1.ContainsKey(Value) then
      begin
        Intersection.Add(Value);
      end;
    end;

    // Convert TList to TArray
    Result := Intersection.ToArray;
  finally
    Set1.Free;
    Set2.Free;
    Intersection.Free;
  end;
end;

procedure PrintArray(const arr: TArray<Integer>);
var
  i: Integer;
begin
  for i := Low(arr) to High(arr) do
    Write(arr[i], ' ');
  Writeln;
end;

var
  ar1, ar2: array of Integer;
  resultArray: TArray<Integer>;
begin
  // Example arrays
  ar1 := [1, 2, 3, 4, 5];
  ar2 := [4, 5, 6, 7, 8];

  // Find intersection
  resultArray := ArrayIntersection(ar1, ar2);

  // Print result
  Writeln('Intersection of arrays:');
  PrintArray(resultArray);

  Readln;
end.
```

