            .padding(16.dp),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        Text("Expenses ($timeFrame)", fontSize = 24.sp)

        // Buttons to switch between time frames
        Row(
            modifier = Modifier.padding(vertical = 16.dp),
            horizontalArrangement = Arrangement.SpaceEvenly
        ) {
            Button(onClick = { timeFrame = "Daily" }) { Text("Daily") }
            Button(onClick = { timeFrame = "Weekly" }) { Text("Weekly") }
            Button(onClick = { timeFrame = "Monthly" }) { Text("Monthly") }
            Button(onClick = { timeFrame = "Yearly" }) { Text("Yearly") }
        }

        // Line chart to display expenses
        LineChart(
            data = LineChartData(
                values = expenseData,
                color = Color.Blue
            ),
            modifier = Modifier
                .fillMaxWidth()
                .height(300.dp)
        )
    }
}

