```css
body {
    font-family: Arial, sans-serif;
    max-width: 800px;
    margin: auto;
}

header, footer {
    text-align: center;
    background-color: #333;
    color: white;
    padding: 1rem;
}

.main {
    margin-top: 2rem;
}

